execute-script.function:
{
    invoice = $draft.copy(transient: false);
    $event.add(`demo.events:Event#invoices`, $invoice);
    $invoice.set(`demo.events:Invoice#currency`, $event.get(`demo.events:Event#currency`));
    scan = $invoice.get(`demo.events:Invoice#scan`);

    values = ifElse(isEmpty($scan), null, {
        result = aiChat(
            [{
                "role": "system",
                "content": "Read the invoice in the image the user provides and return its data as a JSON object. Dates are written as dd.MM.yyyy. Amounts are plain numbers without currency or thousands separators. Write the line descriptions in language {0}.".fill(
                    currentUser().get(`tl.accounts:Person#locale`))
            },
            {
                "role": "user",
                "content": $scan
            }],
            responseFormat: {
                "name": "invoice",
                "schema": {
                    "$schema": "https://json-schema.org/draft/2020-12/schema",
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                        "invoiceNumber": {"type": "string", "description": "The invoice number as printed."},
                        "invoiceDate": {"type": "string", "description": "The invoice date, dd.MM.yyyy."},
                        "dueDate": {"type": "string", "description": "The date payment is due, dd.MM.yyyy."},
                        "taxRate": {"type": "number", "description": "The VAT rate in percent, e.g. 19."},
                        "counterparty": {"type": "string", "description": "The name of the company that issued the invoice."},
                        "lines": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "additionalProperties": false,
                                "properties": {
                                    "description": {"type": "string"},
                                    "quantity": {"type": "number"},
                                    "unitPrice": {"type": "number", "description": "Net price of one unit."}
                                }
                            }
                        }
                    }
                }
            }
        );

        // A model wraps its JSON in a markdown fence often enough that parseJson() on the raw answer
        // fails, so the fence is stripped before parsing - a prompt is a request, this is a parser.
        parsed = regexReplace(regex("(?s)^\\s*```(?:json)?\\s*|\\s*```\\s*$"), $result, "").parseJson();

        // The same schema comes back either as the values or wrapped in its own "properties" key.
        ifElse(isEmpty($parsed["properties"]), $parsed, $parsed["properties"]);
    });

    v = key -> ifElse(isEmpty($values), null, $values[$key]);

    // An amount the model wrote as text ("4.088,80 EUR") is read as the number it means.
    number = x -> ifElse(isEmpty($x), null, {
        text = regexReplace(regex(","), regexReplace(regex("[^0-9,.]"), $x.toString(), ""), ".");
        ifElse(isEmpty($text), null, $text.parseJson());
    });
    day = x -> ifElse(isEmpty($x), null, dateFormat("dd.MM.yyyy").parse($x));

    // The two mandatory values have a fallback, so a scan the model could not read is still filed
    // and the user corrects it in the form, instead of the whole creation being rolled back.
    $invoice.set(`demo.events:Invoice#invoiceNumber`,
        ifElse(isEmpty($v("invoiceNumber")), "?", $v("invoiceNumber")));
    $invoice.set(`demo.events:Invoice#invoiceDate`,
        ifElse(isEmpty($v("invoiceDate")), today(), $day($v("invoiceDate"))));
    $invoice.set(`demo.events:Invoice#dueDate`, $day($v("dueDate")));
    $invoice.set(`demo.events:Invoice#taxRate`, $number($v("taxRate")));
    $invoice.set(`demo.events:Invoice#status`, `demo.events:InvoiceStatus#RECEIVED`);

    // Only a company this application already knows is set; inventing a contact would need an
    // address the scan does not reliably give.
    issuer = $v("counterparty");
    $invoice.set(`demo.events:Invoice#counterparty`, ifElse(isEmpty($issuer), null,
        all(`Contacts:CompanyContact`)
            .filter(c -> $c.get(`Contacts:Contact.all#name`).toLowerCase().stringContains($issuer.toLowerCase())
                || $issuer.toLowerCase().stringContains($c.get(`Contacts:Contact.all#name`).toLowerCase()))
            .firstElement()));

    ifElse(isEmpty($v("lines")), list(), $v("lines")).foreach(l -> {
        line = new(`demo.events:InvoiceLine`);
        $line.set(`demo.events:InvoiceLine#description`, $l["description"]);
        $line.set(`demo.events:InvoiceLine#quantity`, $number($l["quantity"]));
        $line.set(`demo.events:InvoiceLine#unitPrice`, $number($l["unitPrice"]));
        $invoice.add(`demo.events:Invoice#lines`, $line);
    });

    $invoice;
}
